package org.marketreview.nativeapp;
import org.json.*;
import java.util.*;
import java.time.*;
import java.util.regex.*;
import java.util.function.BooleanSupplier;
/** Explicit local document consumption only; never resolves companies or computes valuation. */
final class CandidateBusinessSelection {
 static final String SCHEMA="native-candidate-business-selection/v1";
 static final String BOUNDARY="只消费明确选择的当前本机资料。主营文字匹配不是营收证明；低估值+4仅需求词弱信号，不是估值计算。资料及财务数值保留用户提供/原核验状态；发布时间、当时可获得性和独立核验未知。";
 static final String[] FIELDS={"industry","boards","mainBusinessItems","businessSummary","businessScope"},METRICS={"pe","pb","profitMargin","cashFlow"};
 static void need(boolean b,String s){LocalCandidateModel.require(b,s);}
 static JSONObject object(JSONObject o,String key){JSONObject p=o.optJSONObject(key);return p==null?new JSONObject():p;}
 static JSONArray array(JSONObject o,String key){JSONArray a=o.optJSONArray(key);return a==null?new JSONArray():a;}
 static String compact(String s){return s.replaceAll("[\\s\\p{Z}\\uFEFF]+","").toLowerCase(Locale.ROOT);}
 static JSONArray keywords(String text,JSONArray topics)throws Exception{LinkedHashSet<String> out=new LinkedHashSet<>();for(int i=0;i<topics.length();i++){JSONObject t=topics.getJSONObject(i);out.add(t.getString("name"));JSONArray aliases=array(t,"aliases");for(int j=0;j<aliases.length();j++){need(aliases.get(j) instanceof String&&!compact(aliases.getString(j)).isEmpty(),"主题别名必须为非空明确文字");String a=aliases.getString(j);if(!a.isEmpty()&&compact(text).contains(compact(a)))out.add(a);}}Set<String> stop=new HashSet<>(Arrays.asList("只看","优先","方向","已经","不要","不能","最好","或者","以及","真实","相关","涨太高","主营业务"));Matcher matcher=Pattern.compile("[A-Za-z0-9.]+|[\\u4e00-\\u9fa5]{2,}").matcher(text);while(matcher.find()){String s=matcher.group();if(s.length()<=12&&!stop.contains(s))out.add(s);}out.remove("");JSONArray a=new JSONArray();for(String s:out){if(a.length()==16)break;a.put(s);}return a;}
 static JSONObject demand(JSONObject theme)throws Exception{String text=theme.getJSONObject("demand").getString("text");return new JSONObject().put("text",text).put("keywords",keywords(text,theme.getJSONArray("topics"))).put("preferBusinessMatch",Pattern.compile("主营|主业|业务|营收|产业链|真概念|真实相关").matcher(text).find()).put("lowValuation",text.toLowerCase(Locale.ROOT).contains("低估值"));}
 static JSONObject profile(JSONObject doc,Map<String,String> texts)throws Exception{
  JSONObject p=object(doc,"businessProfile");need("explicit-business-profile/v1".equals(p.optString("schema")),"资料缺少明确businessProfile格式；普通正文不自动抽取");ResearchCompanies.validateReferences(p,texts);JSONObject company=object(p,"company");need(ResearchCompanies.identity(company.optString("instrumentId")),"主营资料必须有明确证券身份");String date=p.optString("asOf");need(date.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"),"主营资料业务日期必须明确");LocalDate.parse(date);String source=doc.optString("sourceUrl");if(source.isEmpty())source=doc.optString("sourceLabel");need(!source.trim().isEmpty()&&source.length()<=512,"主营资料来源链接或标签缺失");need(p.opt("fields") instanceof JSONObject,"主营fields格式无效");need(!p.has("financial")||p.opt("financial") instanceof JSONObject,"财务字段集合格式无效");need(!p.has("quotes")||p.opt("quotes") instanceof JSONObject,"字段引用集合格式无效");JSONObject fields=p.getJSONObject("fields"),quotes=object(p,"quotes"),kept=new JSONObject();JSONArray missing=new JSONArray();
  for(String key:FIELDS){Object value=fields.opt(key);if(value==null||value==JSONObject.NULL){kept.put(key,JSONObject.NULL);missing.put(key);continue;}List<String> values=new ArrayList<>();if(key.equals("boards")||key.equals("mainBusinessItems")){need(value instanceof JSONArray&&((JSONArray)value).length()<=50,key+"格式或数量无效");JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++){Object s=key.equals("boards")?a.get(i):a.getJSONObject(i).opt("name");need(s instanceof String&&!((String)s).trim().isEmpty()&&((String)s).length()<=512,key+"字段须为明确文字");values.add((String)s);}}else{need(value instanceof String&&!((String)value).trim().isEmpty()&&((String)value).length()<=2048,key+"须为明确文字");values.add((String)value);}if(values.isEmpty()){kept.put(key,JSONObject.NULL);missing.put(key);continue;}need(quotes.opt(key) instanceof String,key+"引用须为逐字文字");String q=quotes.getString(key);need(!q.isEmpty()&&q.length()<=4096&&doc.getString("text").contains(q),key+"引用不匹配完整原文");for(String s:values)need(q.contains(s),key+"引用未包含字段值");kept.put(key,value);}
  JSONObject financial=new JSONObject();JSONArray financialMissing=new JSONArray();for(String key:METRICS){Object metric=object(p,"financial").opt(key);if(metric==null||metric==JSONObject.NULL){financial.put(key,JSONObject.NULL);financialMissing.put(key);continue;}need(metric instanceof JSONObject,key+"财务字段格式无效");JSONObject m=(JSONObject)metric;String number=m.optString("value"),unit=m.optString("unit"),q=m.optString("quote");need(m.opt("value") instanceof String&&m.opt("unit") instanceof String&&m.opt("quote") instanceof String&&number.length()<=50&&number.matches("[+-]?[0-9]+(?:\\.[0-9]+)?")&&Double.isFinite(Double.parseDouble(number))&&!unit.trim().isEmpty()&&unit.length()<=80&&!q.isEmpty()&&q.length()<=2048&&q.contains(number)&&q.contains(unit)&&doc.getString("text").contains(q),key+"须有明确数值、单位及逐字原文；不推算");financial.put(key,m);}
  String verification=doc.optString("verification","unverified");need(Arrays.asList("unverified","manuallyVerified").contains(verification),"资料原核验状态无效");return new JSONObject().put("securityId",company.get("instrumentId")).put("documentId",doc.get("id")).put("documentHash",LocalCandidateBackgroundAdapter.sourceDigest(doc)).put("source",source).put("asOf",date).put("verification",verification).put("fields",kept).put("quotes",quotes).put("unknownFields",missing).put("financial",financial).put("unknownFinancial",financialMissing).put("status","provided-unverified");
 }
 static JSONObject unknown(String id)throws Exception{JSONObject f=new JSONObject(),m=new JSONObject();JSONArray uf=new JSONArray(),um=new JSONArray();for(String k:FIELDS){f.put(k,JSONObject.NULL);uf.put(k);}for(String k:METRICS){m.put(k,JSONObject.NULL);um.put(k);}return new JSONObject().put("status","unknown").put("securityId",id).put("reason","未明确选择可用资料；字段未知，不代表公司无业务").put("fields",f).put("financial",m).put("unknownFields",uf).put("unknownFinancial",um);}
 static JSONObject select(JSONObject cat,JSONObject theme,List<String> docIds,BooleanSupplier c)throws Exception{
  CandidateThemeSelection.active(c);CandidateThemeSelection.verify(theme,c);need(docIds.size()<=50&&cat.opt("docs") instanceof JSONArray,"最多明确选择50篇主营资料");Map<String,JSONObject> docs=CandidateThemeSelection.index(cat.getJSONArray("docs"));Map<String,String> texts=new HashMap<>();for(Map.Entry<String,JSONObject> e:docs.entrySet()){need(e.getValue().opt("text") instanceof String,"资料正文格式无效");texts.put(e.getKey(),e.getValue().getString("text"));}Set<String> ids=new HashSet<>(),selected=new HashSet<>(),used=new TreeSet<>();JSONArray ss=theme.getJSONArray("securities");for(int i=0;i<ss.length();i++)selected.add(ss.getJSONObject(i).getString("id"));JSONObject profiles=new JSONObject();
  for(String id:docIds){CandidateThemeSelection.active(c);need(docs.containsKey(id)&&ids.add(id),"所选主营资料已缺失或重复");JSONObject p=profile(docs.get(id),texts);String security=p.getString("securityId");need(selected.contains(security)&&!profiles.has(security),"主营资料证券须在选择范围，且每只最多一篇；不合并冲突日期");profiles.put(security,p);used.add(id);used.add(docs.get(id).getJSONObject("businessProfile").getJSONObject("company").getString("identityDocumentId"));}
  for(String id:selected)if(!profiles.has(id))profiles.put(id,unknown(id));
  JSONArray originals=new JSONArray();JSONObject versions=new JSONObject();for(String id:used){originals.put(docs.get(id));versions.put(id,LocalCandidateBackgroundAdapter.sourceDigest(docs.get(id)));}JSONObject out=new JSONObject().put("schema",SCHEMA).put("themeDigest",LocalCandidateBackgroundAdapter.sourceDigest(theme)).put("documentIds",new JSONArray(docIds)).put("docs",originals).put("versions",versions).put("profiles",profiles).put("demand",demand(theme)).put("boundary",BOUNDARY);need(out.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=2*1024*1024,"完整主营选择超过2MiB，未截断");CandidateThemeSelection.active(c);return new JSONObject(out.toString());
 }
 static void verify(JSONObject held,JSONObject theme,BooleanSupplier c)throws Exception{need(SCHEMA.equals(held.optString("schema")),"主营选择版本不支持");need(LocalCandidateBackgroundAdapter.canonical(select(held,theme,CandidateThemeSelection.strings(held.getJSONArray("documentIds")),c)).equals(LocalCandidateBackgroundAdapter.canonical(held)),"主营正文、需求、来源或证券绑定被改动");}
 static void confirm(JSONObject held,JSONObject cat,JSONObject theme,BooleanSupplier c)throws Exception{verify(held,theme,c);need(LocalCandidateBackgroundAdapter.canonical(select(cat,theme,CandidateThemeSelection.strings(held.getJSONArray("documentIds")),c)).equals(LocalCandidateBackgroundAdapter.canonical(held)),"主营资料或身份原文已变化，请重新预览；旧证据保留");}
 static void clocks(JSONObject held,Instant cut)throws Exception{CandidateThemeSelection.clocks(new JSONObject().put("topics",new JSONArray()).put("relations",new JSONArray()).put("docs",held.getJSONArray("docs")),cut);JSONObject profiles=held.getJSONObject("profiles");Iterator<String> keys=profiles.keys();while(keys.hasNext()){String key=keys.next();if("provided-unverified".equals(profiles.getJSONObject(key).optString("status")))need(!LocalDate.parse(profiles.getJSONObject(key).getString("asOf")).isAfter(cut.atOffset(ZoneOffset.ofHours(8)).toLocalDate()),"主营资料包含未来业务日期");}}
 static String businessText(JSONObject p)throws Exception{JSONObject f=object(p,"fields");List<String> parts=new ArrayList<>();parts.add(f.optString("industry",""));List<String> values=new ArrayList<>();JSONArray a=array(f,"boards");for(int i=0;i<a.length();i++)values.add(a.getString(i));parts.add(String.join(" ",values));values.clear();a=array(f,"mainBusinessItems");for(int i=0;i<a.length();i++)values.add(a.getJSONObject(i).getString("name"));parts.add(String.join(" ",values));parts.add(f.optString("businessSummary",""));parts.add(f.optString("businessScope",""));return String.join(" ",parts);}
 static JSONObject rule(JSONObject p,JSONObject d)throws Exception{JSONArray matches=new JSONArray(),keys=d.getJSONArray("keywords");for(int i=0;i<keys.length();i++)if("provided-unverified".equals(p.optString("status"))&&compact(businessText(p)).contains(compact(keys.getString(i)))&&matches.length()<6)matches.put(keys.get(i));boolean prefer=d.getBoolean("preferBusinessMatch");return new JSONObject().put("matches",matches).put("points",matches.length()>0?(prefer?18:12):(prefer?-6:0)).put("legacyExplanationPoints",matches.length()>0?14:JSONObject.NULL);}
 static String describe(JSONObject held)throws Exception{return "主营 / 估值需求 · 完整证据预览\n"+BOUNDARY+"\n需求："+held.getJSONObject("demand").getString("text")+"\n实际主营规则：命中18/12，偏好未满足-6；旧说明14不另外计分。\n低估值：字面包含时+4，否定短语也沿用旧命中；财务缺数继续未知。\n完整主营选择（原文、身份引用、字段来源及摘要；财务仅用户提供，缺数未知，未计算）：\n"+held.toString(2);}
}
